-- Funder and partner-organisation scholarships, second pass (UK, US, Australia, Ghana), from the funders' own pages, checked 14 Nov 2026. Funding type follows what the official page says is covered. Not verified. Skips ones already held by name.
insert into scholarships (name, funder, country, funding_type, level, criteria, deadline, link, source_url, award_note, school_id, verified, demo)
select v.name, v.funder, v.country, v.funding_type, v.level, v.criteria, v.deadline, v.link, v.link, v.award_note, null, false, false
from (values
($q$Mastercard Foundation Scholars Program at the University of Edinburgh (On-campus Masters)$q$,$q$Mastercard Foundation with University of Edinburgh$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For citizens and residents of an African country (or refugees in one), aged 35 or under, who qualify for a University of Edinburgh one-year taught Masters (generally a UK 2:1 or equal). You must show barriers to education, community leadership and a wish to act on the climate crisis. You must not already hold a postgraduate degree. Partner schools: University of Edinburgh.$q$,NULL::date,$q$https://edinburgh-global.ed.ac.uk/mastercard-foundation-scholars-program/apply-for-a-scholarship/on-campus-postgraduate-scholarships$q$,$q$Full approved tuition, accommodation, travel, living cost stipend and study materials$q$),
($q$Mastercard Foundation Scholars Program at the University of Edinburgh (Online Masters and PG Diploma)$q$,$q$Mastercard Foundation with University of Edinburgh$q$,$q$United Kingdom$q$,$q$Partial$q$,$q$Postgraduate$q$,$q$For citizens and residents of an African country (or refugees in one), aged 35 or under, applying for a part-time online Masters or online Postgraduate Diploma at Edinburgh. Needs strong academics, leadership and community service, and barriers to education. A PG Diploma applicant needs an undergraduate or Masters degree from an African university. Partner schools: University of Edinburgh.$q$,NULL::date,$q$https://edinburgh-global.ed.ac.uk/mastercard-foundation-scholars-program/apply-for-a-scholarship/online-postgraduate-scholarships$q$,$q$Full approved tuition fees, an academic stipend for a laptop and internet, an in-person gathering, and a dedicated Online Coordinator$q$),
($q$Mastercard Foundation Scholars Program at the University of Cambridge$q$,$q$Mastercard Foundation with University of Cambridge$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For nationals and residents of Africa with overseas fee status, studying a full-time Masters at Cambridge for 2027/28. The deadline follows the funding deadline of the chosen course. Partner schools: University of Cambridge.$q$,NULL::date,$q$https://www.student-funding.cam.ac.uk/fund/mastercard-foundation-scholars-program-2026$q$,$q$Full tuition (overseas fees), living stipend, student visa cost, Immigration Health Surcharge, travel, and laptop allowance$q$),
($q$Mastercard Foundation Scholars Program at the University of Oxford (AfOx)$q$,$q$Mastercard Foundation with Africa Oxford Initiative (AfOx), University of Oxford$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For citizens of an African country who live there and hold an Oxford offer for a one-year full-time taught Masters. You must not hold a completed graduate degree and must show community leadership and service. Applications follow the course funding deadline (December or January). Partner schools: University of Oxford.$q$,NULL::date,$q$https://www.afox.ox.ac.uk/education/mastercard-foundation-scholars-program-at-the-university-of-oxford$q$,$q$Tuition fees, living grant at the UKRI minimum doctoral stipend rate, economy return flight, visa and Immigration Health Surcharge fees, settling-in allowance$q$),
($q$Mastercard Foundation Scholars Program at Kwame Nkrumah University of Science and Technology (KNUST)$q$,$q$Mastercard Foundation with KNUST$q$,$q$Ghana$q$,$q$Full$q$,$q$Undergraduate$q$,$q$For Ghanaian school leavers with valid WASSCE or equal results (no older than five years) who meet KNUST entry rules, show critical financial need and a record of leadership. You must not be in another tertiary school. Priority goes to females, displaced persons and persons with disabilities. Partner schools: Kwame Nkrumah University of Science and Technology.$q$,NULL::date,$q$https://mcf.knust.edu.gh/?p=18958$q$,$q$Full tuition, on-campus accommodation, learning materials, transportation and a monthly stipend$q$),
($q$Mastercard Foundation Scholars Program at Ashesi University$q$,$q$Mastercard Foundation with Ashesi University$q$,$q$Ghana$q$,$q$Full$q$,$q$Undergraduate and postgraduate$q$,$q$Applicants do not pick this award. Ashesi's Admissions and Financial Aid Office decides who gets it from the general scholarship application. The page mentions an accelerated Ashesi and Arizona State University route for undergraduate and Masters degrees in five years. Partner schools: Ashesi University.$q$,NULL::date,$q$https://ashesi.edu.gh/the-mastercard-foundation-scholars-programme/$q$,$q$All fees and costs for room and board, and learning resources$q$),
($q$TAGDev 2.0 Scholarship at the University of Cape Coast$q$,$q$RUFORUM and Mastercard Foundation with University of Cape Coast$q$,$q$Ghana$q$,$q$Not stated$q$,$q$Undergraduate$q$,$q$For economically disadvantaged but academically able young Africans, with women, refugees, displaced persons and persons with disabilities strongly encouraged. The 2025/2026 call covered four UCC agriculture programmes: Agriculture, Agricultural Extension and Community Development, Agribusiness and Horticulture. You must apply to UCC and to RUFORUM at the same time. Partner schools: University of Cape Coast.$q$,NULL::date,$q$https://ucc.edu.gh/node/17866$q$,$q$The official page does not say what is covered$q$),
($q$Rotary Peace Fellowship (Master's) at University of Queensland$q$,$q$Rotary Foundation, Rotary Peace Centre at University of Queensland$q$,$q$Australia$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For peace and development professionals with a bachelor's degree, at least three years of full-time relevant work, and at least three years since the last degree. Fellows must study outside their home country, and applicants go through a Rotary district. Partner schools: University of Queensland.$q$,NULL::date,$q$https://rotary.centre.uq.edu.au/node/440$q$,$q$Tuition and university fees, monthly stipend for accommodation and living costs, conference and research funding, fieldwork or internship support, round-trip travel to Brisbane.$q$),
($q$Rotary Peace Fellowship (Master's) at University of Bradford$q$,$q$Rotary Foundation, Rotary Peace Centre at University of Bradford$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For applicants with a bachelor's degree, three years of full-time related work and a commitment to peace. The page sets no nationality rule, but fellows must be placed outside their home country, and apply through a local Rotary district. Partner schools: University of Bradford.$q$,NULL::date,$q$https://www.bradford.ac.uk/faculties/management-sciences-engineering/rotary/$q$,$q$Full funding for tuition, living expenses, applied field experiences and travel, for a 15 month master's.$q$),
($q$Rotary Peace Fellowships (Master's, Duke and UNC Chapel Hill)$q$,$q$Rotary Foundation$q$,$q$United States$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Master's fellowships for peace and development leaders with three years of full-time relevant work, hosted at Duke University and UNC Chapel Hill. Fellows study outside their home country, and a Rotary district must endorse the application; GRE is required at UNC. Partner schools: Duke University, UNC Chapel Hill.$q$,NULL::date,$q$https://www.rotary.org/get-involved/our-programs/peace-fellowships/how-to-become-a-rotary-peace-fellow$q$,$q$Tuition and fees, room and board, round-trip transportation, and research and field study expenses.$q$),
($q$Australia Awards Scholarships (Africa) - Ghana$q$,$q$Australian Government (DFAT) via Australia Awards Africa$q$,$q$Australia$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Master's study for Ghanaian citizens living in Ghana, aged 25 or older, with five years of related work experience, currently employed, an undergraduate degree and no existing master's. IELTS 6.5 or equivalent required.$q$,NULL::date,$q$https://australiaawardsafrica.org/resources/Africa-Profile-2027-Intake.pdf$q$,$q$Full tuition fees, return air travel, establishment allowance, contribution to living expenses, health cover, introductory academic program.$q$),
($q$Destination Australia Program$q$,$q$Australian Government Department of Education$q$,$q$Australia$q$,$q$Partial$q$,$q$Undergraduate and postgraduate$q$,$q$Supports Australian and international students studying at regional campuses of eligible Australian providers, Certificate IV to Doctorate. Applications are made to the participating regional provider.$q$,NULL::date,$q$https://internationaleducation.gov.au/News/Latest-News/Pages/Destination-Australia.aspx$q$,$q$$15,000 per scholarship, covering study and living expenses.$q$),
($q$Felix Scholarships (Developing Countries Master's)$q$,$q$Felix Trust$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$One master's award for a candidate from a developing country, aimed mainly at Africa. Needs at least a first-class bachelor's degree, no degree from a university outside the home country, financial need, and a plan to return home. Full-time study only. Partner schools: University of Reading.$q$,NULL::date,$q$https://reading.ac.uk/ready-to-study/study/fees-and-funding/fees-and-funding-pg/felix-scholarships$q$,$q$Tuition at international rate, stipend of about 17,894 pounds, allowances for clothes and books, and a return flight home.$q$),
($q$Margaret McNamara Education Grants (US and Canada Program)$q$,$q$Margaret McNamara Education Grants (MMEG)$q$,$q$United States$q$,$q$Not stated$q$,$q$Undergraduate and postgraduate$q$,$q$For women aged 25 or older from countries on the MMEG eligibility list (Ghana is on the list), already enrolled full-time in an in-person programme in the US or Canada with a valid student visa. Not for US or Canadian citizens or residents.$q$,NULL::date,$q$https://www.mmeg.org/apply$q$,$q$The page does not state the grant amount or what it covers.$q$),
($q$GREAT Scholarships Ghana$q$,$q$British Council$q$,$q$United Kingdom$q$,$q$Partial$q$,$q$Postgraduate$q$,$q$For passport holders and permanent residents of Ghana with an undergraduate degree, applying to one-year taught postgraduate courses at participating UK universities for 2026-27. Partner schools: Anglia Ruskin University, Birmingham Newman University, Durham University, Edge Hill University, Imperial College London, Kingston University London, Lancaster University, Liverpool Hope University, Royal Holloway, University of London, University of Edinburgh, University of Manchester, University of Dundee.$q$,NULL::date,$q$https://study-uk.britishcouncil.org/scholarships-funding/great-scholarships/ghana$q$,$q$10,000 pounds towards tuition fees.$q$),
($q$Poler Family Oxford Scholarship$q$,$q$Poler Family Foundation$q$,$q$United Kingdom$q$,$q$Partial$q$,$q$Postgraduate$q$,$q$For outstanding candidates ordinarily resident in Africa admitted to the Master of Public Policy at the University of Oxford. No separate application. Partner schools: University of Oxford (Blavatnik School of Government).$q$,NULL::date,$q$https://www.bsg.ox.ac.uk/node/9151$q$,$q$Full fees and a contribution towards living expenses.$q$),
($q$Cambridge Trust International Scholarship$q$,$q$The Cambridge Trust$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For highly ranked applicants from countries other than the UK or Ireland. No separate application; apply for admission to Cambridge by the funding deadline for your course. Partner schools: University of Cambridge.$q$,NULL::date,$q$https://www.cambridgetrust.org/scholarship/cambridge-international-scholarship/$q$,$q$Tuition at international rate, annual maintenance for a single person, student visa and Immigration Health Surcharge.$q$),
($q$Ertegun Graduate Scholarship Programme in the Humanities$q$,$q$Ertegun Scholarship Programme$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Students from all countries can apply. For new full-time master's or doctoral students on eligible humanities courses at Oxford. Apply by the early January course deadline. Partner schools: University of Oxford.$q$,NULL::date,$q$https://www.ertegun.ox.ac.uk/scholarships$q$,$q$Course fees in full and a living-costs grant of 21,805 pounds a year (2026-27).$q$)
) as v(name, funder, country, funding_type, level, criteria, deadline, link, award_note)
where not exists (select 1 from scholarships s where s.school_id is null and lower(s.name) = lower(v.name));
